<?php

declare(strict_types=1);

require_once __DIR__.'/ProductionLifecycleGuard.php';
require_once __DIR__.'/MailService.php';

final class LatePickupService
{
    public static function settings(PDO $db,int $productionId):array
    {
        $s=$db->prepare('SELECT * FROM production_late_pickup_settings WHERE production_id=:production');$s->execute(['production'=>$productionId]);return$s->fetch()?:['production_id'=>$productionId,'occurrence_threshold'=>3,'grace_minutes'=>10,'notice_template'=>null];
    }

    public static function saveSettings(PDO $db,int $productionId,int $actorId,int $threshold,int $grace,?string $template):void
    {
        ProductionLifecycleGuard::assertWritable($db,$productionId);if($threshold<1||$threshold>20||$grace<0||$grace>120)throw new RuntimeException('Use a threshold from 1 to 20 and a grace period from 0 to 120 minutes.');$template=trim((string)$template);if(mb_strlen($template)>5000)throw new RuntimeException('The notice template is too long.');$q=$db->prepare('INSERT INTO production_late_pickup_settings (production_id,occurrence_threshold,grace_minutes,notice_template,updated_by_user_id) VALUES (:production,:threshold,:grace,:template,:actor) ON DUPLICATE KEY UPDATE occurrence_threshold=VALUES(occurrence_threshold),grace_minutes=VALUES(grace_minutes),notice_template=VALUES(notice_template),updated_by_user_id=VALUES(updated_by_user_id)');$q->execute(['production'=>$productionId,'threshold'=>$threshold,'grace'=>$grace,'template'=>$template?:null,'actor'=>$actorId]);$students=$db->prepare('SELECT DISTINCT student_user_id FROM late_pickup_occurrences WHERE production_id=:production');$students->execute(['production'=>$productionId]);foreach($students->fetchAll(PDO::FETCH_COLUMN) as $studentId)self::recompute($db,$productionId,(int)$studentId,$actorId);self::audit($db,$actorId,'late_pickup.settings_updated','production',$productionId,'Updated late pickup review settings.',['threshold'=>$threshold,'grace_minutes'=>$grace]);
    }

    public static function forSchedule(PDO $db,int $scheduleItemId):array
    {
        $s=$db->prepare('SELECT o.*,CASE WHEN o.late_minutes>COALESCE(s.grace_minutes,10) AND o.voided_at IS NULL THEN 1 ELSE 0 END qualifies FROM late_pickup_occurrences o LEFT JOIN production_late_pickup_settings s ON s.production_id=o.production_id WHERE o.schedule_item_id=:item');$s->execute(['item'=>$scheduleItemId]);$out=[];foreach($s->fetchAll() as $row)$out[(int)$row['student_user_id']]=$row;return$out;
    }

    public static function record(PDO $db,int $scheduleItemId,int $studentId,int $actorId,?string $actualInput,string $reason=''):void
    {
        ProductionLifecycleGuard::assertScheduleItemWritable($db,$scheduleItemId);$item=$db->prepare("SELECT si.id,si.production_id,si.ends_at,si.status,p.lifecycle_stage,p.is_active FROM schedule_items si JOIN productions p ON p.id=si.production_id WHERE si.id=:id FOR UPDATE");$item->execute(['id'=>$scheduleItemId]);$event=$item->fetch();if(!$event||$event['status']!=='active')throw new RuntimeException('Late checkout cannot be changed for a cancelled event.');if(empty($event['ends_at']))throw new RuntimeException('Set the schedule item end time before recording a late checkout.');$eligible=$db->prepare("SELECT 1 FROM production_memberships pm JOIN users u ON u.id=pm.user_id AND u.active=1 AND u.account_status='active' WHERE pm.production_id=:production AND pm.user_id=:student AND pm.audience_type='student' AND pm.status='active'");$eligible->execute(['production'=>(int)$event['production_id'],'student'=>$studentId]);if(!$eligible->fetchColumn())throw new RuntimeException('That Student is not an active Student in this production.');$current=$db->prepare('SELECT * FROM late_pickup_occurrences WHERE schedule_item_id=:item AND student_user_id=:student FOR UPDATE');$current->execute(['item'=>$scheduleItemId,'student'=>$studentId]);$before=$current->fetch();$reason=trim($reason);
        if(trim((string)$actualInput)===''){if(!$before||$before['voided_at']!==null)return;if($reason===''||mb_strlen($reason)>1000)throw new RuntimeException('A documented reversal reason is required to clear a late checkout.');$db->prepare('UPDATE late_pickup_occurrences SET voided_at=CURRENT_TIMESTAMP,voided_by_user_id=:actor,void_reason=:reason,corrected_at=CURRENT_TIMESTAMP,correction_reason=:reason2 WHERE id=:id')->execute(['actor'=>$actorId,'reason'=>$reason,'reason2'=>$reason,'id'=>(int)$before['id']]);self::revision($db,(int)$before['id'],$actorId,'voided',$before,null,$reason);self::recompute($db,(int)$event['production_id'],$studentId,$actorId);return;}
        $actual=self::dateTime($actualInput);$expected=new DateTimeImmutable((string)$event['ends_at']);$settings=self::settings($db,(int)$event['production_id']);$late=max(0,(int)floor(($actual->getTimestamp()-$expected->getTimestamp())/60));if($late<=0){if($before&&$before['voided_at']===null){if($reason==='')throw new RuntimeException('This pickup is not after the scheduled release. Enter a reversal reason to clear the previous occurrence.');self::record($db,$scheduleItemId,$studentId,$actorId,null,$reason);}return;}
        $new=['actual_checkout_at'=>$actual->format('Y-m-d H:i:s'),'expected_release_at'=>$expected->format('Y-m-d H:i:s'),'late_minutes'=>$late];if(!$before){$q=$db->prepare('INSERT INTO late_pickup_occurrences (schedule_item_id,production_id,student_user_id,actual_checkout_at,expected_release_at,late_minutes,recorded_by_user_id) VALUES (:item,:production,:student,:actual,:expected,:late,:actor)');$q->execute(['item'=>$scheduleItemId,'production'=>(int)$event['production_id'],'student'=>$studentId,'actual'=>$new['actual_checkout_at'],'expected'=>$new['expected_release_at'],'late'=>$late,'actor'=>$actorId]);$id=(int)$db->lastInsertId();self::revision($db,$id,$actorId,'created',null,$new,null);}else{$changed=$before['actual_checkout_at']!==$new['actual_checkout_at']||$before['expected_release_at']!==$new['expected_release_at']||(int)$before['late_minutes']!==$late||$before['voided_at']!==null;if(!$changed)return;if($reason===''||mb_strlen($reason)>1000)throw new RuntimeException('Enter a correction reason when changing a saved late checkout.');$db->prepare('UPDATE late_pickup_occurrences SET actual_checkout_at=:actual,expected_release_at=:expected,late_minutes=:late,corrected_at=CURRENT_TIMESTAMP,correction_reason=:reason,voided_at=NULL,voided_by_user_id=NULL,void_reason=NULL WHERE id=:id')->execute(['actual'=>$new['actual_checkout_at'],'expected'=>$new['expected_release_at'],'late'=>$late,'reason'=>$reason,'id'=>(int)$before['id']]);self::revision($db,(int)$before['id'],$actorId,$before['voided_at']?'restored':'corrected',$before,$new,$reason);}
        self::recompute($db,(int)$event['production_id'],$studentId,$actorId);
    }

    public static function dashboard(PDO $db,int $productionId):array
    {
        self::syncQueueStatuses($db,$productionId);
        $s=$db->prepare("SELECT r.*,CONCAT(u.first_name,' ',u.last_name) student_name,n.id notice_id,n.subject,n.body,n.status notice_status,n.revision_number,n.approved_at,n.queued_at FROM late_pickup_reviews r JOIN users u ON u.id=r.student_user_id LEFT JOIN late_pickup_notice_drafts n ON n.id=(SELECT n2.id FROM late_pickup_notice_drafts n2 WHERE n2.review_id=r.id ORDER BY n2.id DESC LIMIT 1) WHERE r.production_id=:production ORDER BY FIELD(r.status,'open','below_threshold','dismissed','resolved'),u.last_name,u.first_name");$s->execute(['production'=>$productionId]);$rows=$s->fetchAll();$history=$db->prepare("SELECT o.*,si.title,si.starts_at,CASE WHEN o.late_minutes>COALESCE(cfg.grace_minutes,10) AND o.voided_at IS NULL THEN 1 ELSE 0 END qualifies FROM late_pickup_occurrences o JOIN schedule_items si ON si.id=o.schedule_item_id LEFT JOIN production_late_pickup_settings cfg ON cfg.production_id=o.production_id WHERE o.production_id=:production AND o.student_user_id=:student ORDER BY si.starts_at DESC,o.id DESC");$revisions=$db->prepare('SELECT revision_number,subject,actor_user_id,created_at FROM late_pickup_notice_revisions WHERE notice_id=:notice ORDER BY revision_number DESC');$recipients=$db->prepare('SELECT r.recipient_name,r.recipient_email,COALESCE(q.status,r.queue_status) queue_status,q.sent_at,q.last_error FROM late_pickup_notice_recipients r LEFT JOIN email_queue q ON q.id=r.email_queue_id WHERE r.notice_id=:notice ORDER BY r.id');foreach($rows as &$row){$history->execute(['production'=>$productionId,'student'=>(int)$row['student_user_id']]);$row['occurrences']=$history->fetchAll();$row['guardians']=self::guardians($db,(int)$row['student_user_id']);$row['notice_revisions']=[];$row['recipients']=[];if($row['notice_id']){$revisions->execute(['notice'=>(int)$row['notice_id']]);$row['notice_revisions']=$revisions->fetchAll();$recipients->execute(['notice'=>(int)$row['notice_id']]);$row['recipients']=$recipients->fetchAll();}}unset($row);return$rows;
    }

    public static function saveDraft(PDO $db,int $productionId,int $noticeId,int $actorId,string $subject,string $body,bool $submit):void
    {
        ProductionLifecycleGuard::assertWritable($db,$productionId);$subject=trim($subject);$body=trim($body);if($subject===''||mb_strlen($subject)>255||$body===''||mb_strlen($body)>8000)throw new RuntimeException('Enter a subject and notice text within the allowed lengths.');$s=$db->prepare("SELECT * FROM late_pickup_notice_drafts WHERE id=:id AND production_id=:production AND status IN ('draft','pending_approval','approved') FOR UPDATE");$s->execute(['id'=>$noticeId,'production'=>$productionId]);$notice=$s->fetch();if(!$notice)throw new RuntimeException('That notice can no longer be edited.');$revision=(int)$notice['revision_number']+1;$status=$submit?'pending_approval':'draft';$db->prepare('UPDATE late_pickup_notice_drafts SET subject=:subject,body=:body,status=:status,revision_number=:revision,approved_by_user_id=NULL,approved_at=NULL WHERE id=:id')->execute(['subject'=>$subject,'body'=>$body,'status'=>$status,'revision'=>$revision,'id'=>$noticeId]);$db->prepare('INSERT INTO late_pickup_notice_revisions (notice_id,revision_number,subject,body,actor_user_id) VALUES (:notice,:revision,:subject,:body,:actor)')->execute(['notice'=>$noticeId,'revision'=>$revision,'subject'=>$subject,'body'=>$body,'actor'=>$actorId]);self::audit($db,$actorId,'late_pickup.notice_revised','late_pickup_notice',$noticeId,'Revised late pickup guardian notice.',['revision'=>$revision,'status'=>$status]);
    }

    public static function approve(PDO $db,int $productionId,int $noticeId,int $actorId):void
    {
        ProductionLifecycleGuard::assertWritable($db,$productionId);$guard=self::noticeWithCurrentGuardians($db,$productionId,$noticeId,['pending_approval']);if(!$guard['guardians'])throw new RuntimeException('No current active guardian with an eligible email address is available.');$db->prepare("UPDATE late_pickup_notice_drafts SET status='approved',approved_by_user_id=:actor,approved_at=CURRENT_TIMESTAMP WHERE id=:id")->execute(['actor'=>$actorId,'id'=>$noticeId]);self::audit($db,$actorId,'late_pickup.notice_approved','late_pickup_notice',$noticeId,'Approved late pickup guardian notice.',['guardian_count'=>count($guard['guardians'])]);
    }

    public static function send(PDO $db,int $productionId,int $noticeId,int $actorId):int
    {
        ProductionLifecycleGuard::assertWritable($db,$productionId);$bundle=self::noticeWithCurrentGuardians($db,$productionId,$noticeId,['approved','queued']);$notice=$bundle['notice'];if($notice['status']==='queued')return 0;if(!$bundle['guardians'])throw new RuntimeException('No current active guardian with an eligible email address is available.');$queued=0;foreach($bundle['guardians'] as $guardian){$dedupe='late-pickup-notice-'.$noticeId.'-guardian-'.(int)$guardian['id'].'-revision-'.(int)$notice['revision_number'];$queueId=MailService::queue($db,(int)$guardian['id'],(string)$guardian['email'],(string)$guardian['name'],'system',(string)$notice['subject'],(string)$notice['body'],null,$dedupe);$insert=$db->prepare("INSERT INTO late_pickup_notice_recipients (notice_id,guardian_user_id,recipient_name,recipient_email,email_queue_id,queue_status,content_snapshot_json) VALUES (:notice,:guardian,:name,:email,:queue,'queued',:snapshot) ON DUPLICATE KEY UPDATE email_queue_id=COALESCE(email_queue_id,VALUES(email_queue_id))");$insert->execute(['notice'=>$noticeId,'guardian'=>(int)$guardian['id'],'name'=>$guardian['name'],'email'=>$guardian['email'],'queue'=>$queueId?:null,'snapshot'=>json_encode(['subject'=>$notice['subject'],'body'=>$notice['body'],'revision'=>(int)$notice['revision_number']],JSON_THROW_ON_ERROR)]);if($queueId)$queued++;}$db->prepare("UPDATE late_pickup_notice_drafts SET status='queued',queued_by_user_id=:actor,queued_at=CURRENT_TIMESTAMP WHERE id=:id AND status='approved'")->execute(['actor'=>$actorId,'id'=>$noticeId]);self::audit($db,$actorId,'late_pickup.notice_queued','late_pickup_notice',$noticeId,'Queued approved late pickup guardian notice.',['recipient_count'=>count($bundle['guardians']),'queue_count'=>$queued]);return$queued;
    }

    public static function resolve(PDO $db,int $productionId,int $reviewId,int $actorId,string $status,string $reason):void
    {
        ProductionLifecycleGuard::assertWritable($db,$productionId);if(!in_array($status,['dismissed','resolved'],true)||trim($reason)===''||mb_strlen(trim($reason))>1000)throw new RuntimeException('Choose dismiss or resolve and enter a reason.');$q=$db->prepare('UPDATE late_pickup_reviews SET status=:status,resolution_reason=:reason,resolved_at=CURRENT_TIMESTAMP,resolved_by_user_id=:actor WHERE id=:id AND production_id=:production');$q->execute(['status'=>$status,'reason'=>trim($reason),'actor'=>$actorId,'id'=>$reviewId,'production'=>$productionId]);if(!$q->rowCount())throw new RuntimeException('That review is unavailable.');self::audit($db,$actorId,'late_pickup.review_'.$status,'late_pickup_review',$reviewId,'Closed late pickup review.',['reason'=>trim($reason)]);
    }

    public static function familyNotices(PDO $db,int $viewerId):array
    {
        $s=$db->prepare("SELECT n.id,n.subject,n.body,n.status,n.approved_at,n.queued_at,p.title production_title,CONCAT(student.first_name,' ',student.last_name) student_name FROM late_pickup_notice_drafts n JOIN productions p ON p.id=n.production_id JOIN users student ON student.id=n.student_user_id WHERE n.status IN ('approved','queued','sent') AND (n.student_user_id=:student OR EXISTS(SELECT 1 FROM family_relationships fr WHERE fr.student_user_id=n.student_user_id AND fr.guardian_user_id=:guardian AND fr.status='active')) ORDER BY COALESCE(n.queued_at,n.approved_at) DESC,n.id DESC");$s->execute(['student'=>$viewerId,'guardian'=>$viewerId]);return$s->fetchAll();
    }

    private static function recompute(PDO $db,int $productionId,int $studentId,int $actorId):void
    {
        $settings=self::settings($db,$productionId);$q=$db->prepare('SELECT COUNT(*) FROM late_pickup_occurrences WHERE production_id=:production AND student_user_id=:student AND voided_at IS NULL AND late_minutes>:grace');$q->execute(['production'=>$productionId,'student'=>$studentId,'grace'=>(int)$settings['grace_minutes']]);$count=(int)$q->fetchColumn();$threshold=(int)$settings['occurrence_threshold'];$find=$db->prepare('SELECT * FROM late_pickup_reviews WHERE production_id=:production AND student_user_id=:student FOR UPDATE');$find->execute(['production'=>$productionId,'student'=>$studentId]);$review=$find->fetch();if($count>=$threshold){if(!$review){$db->prepare("INSERT INTO late_pickup_reviews (production_id,student_user_id,occurrence_count,threshold_at_open,status) VALUES (:production,:student,:count,:threshold,'open')")->execute(['production'=>$productionId,'student'=>$studentId,'count'=>$count,'threshold'=>$threshold]);$reviewId=(int)$db->lastInsertId();self::createDraft($db,$reviewId,$productionId,$studentId,$actorId,$settings);}else{$reviewId=(int)$review['id'];$db->prepare("UPDATE late_pickup_reviews SET occurrence_count=:count,threshold_at_open=:threshold,status=IF(status='below_threshold','open',status),resolved_at=IF(status='below_threshold',NULL,resolved_at),resolved_by_user_id=IF(status='below_threshold',NULL,resolved_by_user_id) WHERE id=:id")->execute(['count'=>$count,'threshold'=>$threshold,'id'=>$reviewId]);if(in_array($review['status'],['below_threshold','dismissed','resolved'],true))self::createDraft($db,$reviewId,$productionId,$studentId,$actorId,$settings);}}elseif($review){$db->prepare("UPDATE late_pickup_reviews SET occurrence_count=:count,status='below_threshold',resolution_reason='Occurrence count moved below the configured threshold after correction or reversal.',resolved_at=CURRENT_TIMESTAMP,resolved_by_user_id=:actor WHERE id=:id")->execute(['count'=>$count,'actor'=>$actorId,'id'=>(int)$review['id']]);$db->prepare("UPDATE late_pickup_notice_drafts SET status='superseded' WHERE review_id=:review AND status IN ('draft','pending_approval','approved')")->execute(['review'=>(int)$review['id']]);}}

    private static function createDraft(PDO $db,int $reviewId,int $productionId,int $studentId,int $actorId,array $settings):void
    {
        $existing=$db->prepare("SELECT 1 FROM late_pickup_notice_drafts WHERE review_id=:review AND status IN ('draft','pending_approval','approved','queued')");$existing->execute(['review'=>$reviewId]);if($existing->fetchColumn())return;$student=$db->prepare('SELECT first_name FROM users WHERE id=:id');$student->execute(['id'=>$studentId]);$name=(string)$student->fetchColumn();$dates=$db->prepare("SELECT si.starts_at,o.actual_checkout_at,o.expected_release_at FROM late_pickup_occurrences o JOIN schedule_items si ON si.id=o.schedule_item_id WHERE o.production_id=:production AND o.student_user_id=:student AND o.voided_at IS NULL ORDER BY si.starts_at");$dates->execute(['production'=>$productionId,'student'=>$studentId]);$lines=[];foreach($dates->fetchAll() as $row)$lines[]='- '.date('M j, Y',strtotime((string)$row['starts_at'])).': pickup about '.date('g:i A',strtotime((string)$row['actual_checkout_at'])).' (release '.date('g:i A',strtotime((string)$row['expected_release_at'])).')';$body=trim((string)($settings['notice_template']??''));if($body==='')$body="Hello,\n\nWe are writing to review {$name}'s recent pickup times:\n\n".implode("\n",$lines)."\n\nPlease plan for pickup at the scheduled release time. Continued late pickups may have financial repercussions only if permitted under CTSMD's actual policy; this notice does not assess a fee.\n\nThank you,\nCTSMD";$subject='Pickup-time review';$q=$db->prepare("INSERT INTO late_pickup_notice_drafts (review_id,production_id,student_user_id,subject,body,status,created_by_user_id) VALUES (:review,:production,:student,:subject,:body,'draft',:actor)");$q->execute(['review'=>$reviewId,'production'=>$productionId,'student'=>$studentId,'subject'=>$subject,'body'=>$body,'actor'=>$actorId]);$noticeId=(int)$db->lastInsertId();$db->prepare('INSERT INTO late_pickup_notice_revisions (notice_id,revision_number,subject,body,actor_user_id) VALUES (:notice,1,:subject,:body,:actor)')->execute(['notice'=>$noticeId,'subject'=>$subject,'body'=>$body,'actor'=>$actorId]);self::audit($db,$actorId,'late_pickup.threshold_crossed','late_pickup_review',$reviewId,'Opened late pickup staff review and draft notice.',['occurrence_threshold'=>(int)$settings['occurrence_threshold']]);
    }

    private static function noticeWithCurrentGuardians(PDO $db,int $productionId,int $noticeId,array $statuses):array
    {
        $ph=implode(',',array_fill(0,count($statuses),'?'));$s=$db->prepare("SELECT * FROM late_pickup_notice_drafts WHERE id=? AND production_id=? AND status IN ($ph) FOR UPDATE");$s->execute(array_merge([$noticeId,$productionId],$statuses));$notice=$s->fetch();if(!$notice)throw new RuntimeException('That notice is not in the required state.');$student=$db->prepare("SELECT 1 FROM users u JOIN production_memberships pm ON pm.user_id=u.id AND pm.production_id=:production AND pm.audience_type='student' AND pm.status='active' WHERE u.id=:student AND u.active=1 AND u.account_status='active'");$student->execute(['production'=>$productionId,'student'=>(int)$notice['student_user_id']]);if(!$student->fetchColumn())throw new RuntimeException('The Student is no longer active in this production.');return['notice'=>$notice,'guardians'=>self::guardians($db,(int)$notice['student_user_id'])];
    }
    private static function guardians(PDO $db,int $studentId):array{$s=$db->prepare("SELECT u.id,CONCAT(u.first_name,' ',u.last_name) name,u.email FROM family_relationships fr JOIN users u ON u.id=fr.guardian_user_id AND u.active=1 AND u.account_status='active' WHERE fr.student_user_id=:student AND fr.status='active' AND u.email IS NOT NULL AND u.email<>'' ORDER BY fr.is_primary DESC,u.id");$s->execute(['student'=>$studentId]);return array_values(array_filter($s->fetchAll(),static fn(array $g):bool=>filter_var($g['email'],FILTER_VALIDATE_EMAIL)!==false));}
    private static function syncQueueStatuses(PDO $db,int $productionId):void
    {
        $s=$db->prepare("SELECT n.id,GROUP_CONCAT(DISTINCT q.status) statuses FROM late_pickup_notice_drafts n JOIN late_pickup_notice_recipients r ON r.notice_id=n.id LEFT JOIN email_queue q ON q.id=r.email_queue_id WHERE n.production_id=:production AND n.status IN ('queued','sent','failed') GROUP BY n.id");$s->execute(['production'=>$productionId]);$update=$db->prepare('UPDATE late_pickup_notice_drafts SET status=:status WHERE id=:id');foreach($s->fetchAll() as $row){$statuses=explode(',',(string)$row['statuses']);$status=count($statuses)===1&&$statuses[0]==='sent'?'sent':((array_intersect($statuses,['queued','sending']))?'queued':((array_intersect($statuses,['failed','suppressed']))?'failed':'queued'));$update->execute(['status'=>$status,'id'=>(int)$row['id']]);}
    }
    private static function revision(PDO $db,int $occurrenceId,int $actor,string $action,?array $old,?array $new,?string $reason):void{$q=$db->prepare('INSERT INTO late_pickup_occurrence_revisions (occurrence_id,actor_user_id,action,original_json,new_json,reason) VALUES (:occurrence,:actor,:action,:old,:new,:reason)');$q->execute(['occurrence'=>$occurrenceId,'actor'=>$actor,'action'=>$action,'old'=>$old?json_encode($old,JSON_THROW_ON_ERROR):null,'new'=>$new?json_encode($new,JSON_THROW_ON_ERROR):null,'reason'=>$reason]);}
    private static function dateTime(string $value):DateTimeImmutable{try{$date=new DateTimeImmutable($value);}catch(Throwable){throw new RuntimeException('Enter a valid actual pickup time.');}return$date;}
    private static function audit(PDO $db,int $actor,string $event,string $type,int $id,string $summary,array $meta):void{$q=$db->prepare('INSERT INTO audit_events (actor_user_id,event_type,subject_type,subject_id,summary,metadata_json) VALUES (:actor,:event,:type,:id,:summary,:meta)');$q->execute(['actor'=>$actor,'event'=>$event,'type'=>$type,'id'=>$id,'summary'=>$summary,'meta'=>json_encode($meta,JSON_THROW_ON_ERROR)]);}
}
